contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take parameters to call either openMakeFor or openTakeFor with an amount and account.
    // The test will compute the positionFee as amount * abs(price) * feeRate via public getters
    // and assert that either the call reverted, or that address(c).balance did not increase
    // (the product charges fees through collateral, not by accepting ether), and that the
    // computed position fee is non-negative (i.e., not underflowed) and consistent with UFixed18 API
    function run(address account, uint256 amountRaw, bool makeNotTake) public payable {
        require(address(this).balance >= 0);
        // Normalize an amount into UFixed18 by using UFixed18Lib.ONE = 1e18 units expected by c; we cannot construct UFixed18 directly here.
        // Instead we will pass arbitrary uint256 and rely on c's openMakeFor/openTakeFor accepting UFixed18 type at ABI-level (uint256).

        // Read pre-state observable values
        uint256 beforeBalance = address(c).balance;
        uint256 latestVer = c.latestVersion();

        // Try to fetch oracle price at latestVersion; if latestVer==0 some operations may revert later, but view is allowed
        // Use try/catch for external mutating calls to detect reverts
        bool reverted = false;
        if (makeNotTake) {
            try c.openMakeFor(account, amountRaw) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, amountRaw) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint256 afterBalance = address(c).balance;

        // The general rule we assert:
        // - The contract's Ether balance must not increase as a result of opening positions (fees are settled via collateral, not by sending ETH to the product contract).
        // - And the call either reverted or the balance stayed the same.
        assert(reverted || afterBalance <= beforeBalance);
    }

    receive() external payable {}
}

