contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will fuzz: account, amount, isMake (1=openMakeFor, 0=openTakeFor)
    function run(address account, uint256 rawAmount, bool isMake) public payable {
        // sanitize amount to be within reasonable range to avoid overflow in UFixed18.wrap semantics
        uint256 amount = rawAmount % 1e30;

        // read some before-state via public getters
        uint256 beforeLatest = c.latestVersion();
        bool beforeClosed = c.closed();
        // account-visible pre and position maintenance values
        // These are view calls and allowed in asserts
        // We don't require any precondition on controller, or owner — calls may revert which we catch.

        bool reverted;
        // perform the action under test: either openMakeFor or openTakeFor
        try this.doCall(account, amount, isMake) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call, read observable state
        uint256 afterLatest = c.latestVersion();
        bool afterClosed = c.closed();

        // General rule asserted:
        // If the call did not revert then the product must not transition from open to closed as a side-effect of a single openMake/openTake;
        // and the latestVersion should be >= beforeLatest (settle may advance it). Also, if beforeClosed was true then any modifying open should have reverted.
        assert((reverted && (!beforeClosed || reverted)) || (!reverted && afterClosed == beforeClosed && afterLatest >= beforeLatest));
    }

    // helper that actually calls c so we can catch reverts in run()
    function doCall(address account, uint256 amount, bool isMake) public {
        // construct a UFixed18 from uint by calling c.openMakeFor/openTakeFor which expect UFixed18 type; but we cannot construct type UFixed18 here.
        // However solidity allows passing uint256 to functions expecting UFixed18 because it's a user-defined type alias to uint256 in ABI.
        if (isMake) {
            c.openMakeFor(account, UFixed18.wrap(amount));
        } else {
            c.openTakeFor(account, UFixed18.wrap(amount));
        }
    }

    receive() external payable {}
}

