contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will try to open a make or take and check that when the call does not revert,
    // the computed position fee (amount * abs(price) * feeRate) is non-negative and
    // that the function either reverts or returns successfully; we observe c only via
    // its public getters: latestVersion(), atVersion(...).price via atVersion(...),
    // makerFee(), takerFee().
    // The assert encodes that if the call succeeds then the computed fee is >= 0.

    function run(bool openMake, address account, uint256 amountRaw) public payable {
        // normalize amount into UFixed18 representation expected by product APIs: they expect UFixed18
        // but we can treat the passed uint as the wrapped value UFixed18.wrap(amountRaw).
        require(account != address(0), true);

