contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test that when opening a take or make, the contract computes a position fee
    // equal to amount * |price| * feeRate and if that positionFee.isZero() then the function
    // still executes (doesn't revert due to fee logic) and otherwise the fee is attempted to be
    // charged (we only can observe no revert). We assert that in all cases the call either
    // succeeds or reverts consistent with the computed positionFee being zero/non-zero.

    // Because we cannot inspect internal calls to controller().collateral(), we assert a weaker
    // general rule: both openTakeFor and openMakeFor do not revert when the computed positionFee is zero,
    // and may revert otherwise. We compute the same positionFee using public getters: latestVersion() and atVersion.

    function run(bool doMake, address account, UFixed18 amount) public payable {
        require(account != address(0) ? true : true);

        // Read latest oracle version and price to compute expected position fee
        uint256 lv = c.latestVersion();
        // If latestVersion is 0, many operations revert (oracle bootstrapping). We allow any behavior then,
        // so restrict to lv != 0 to make assertion meaningful.
        require(lv != 0, "bootstrap");

        // read oracle version struct
        IOracleProvider.OracleVersion memory v = c.atVersion(lv);
        // compute price.abs() via Fixed18.abs exposed through Fixed18Lib as UFixed18 via public function on library types
        UFixed18 priceAbs = v.price.abs();
        // fee rates
        UFixed18 makerFee = c.makerFee();
        UFixed18 takerFee = c.takerFee();

        // compute expected position fees for make and take: amount * priceAbs * fee
        UFixed18 expectedTakeFee = amount.mul(priceAbs).mul(takerFee);
        UFixed18 expectedMakeFee = amount.mul(priceAbs).mul(makerFee);

        bool reverted;
        if (doMake) {
            // call openMakeFor and catch revert
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            // If computed expectedMakeFee is zero then the call must not revert due to fee charging logic
            // (it may still revert for other reasons like maker limit; thus we only assert implication: if not reverted then okay,
            // and if expectedMakeFee.isZero() then reverted must be false).
            assert(expectedMakeFee.isZero() == true ? reverted == false : true);
        } else {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
            assert(expectedTakeFee.isZero() == true ? reverted == false : true);
        }
    }

    receive() external payable {}
}

