contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that invoking openTakeFor/openMakeFor leads to only non-positive immediate collateral settlement
    // as observed via that the test contract (msg.sender) does not receive ETH from c and that calls either revert or succeed.
    // We cannot observe collateral internals; instead we assert that c does not send Ether to this contract during the call
    // (i.e., address(this).balance does not increase). We also assert that if the position fee computed by the product's
    // internal math would be zero (based on current oracle price and fee rates), then the call does not revert solely due to fees.

    receive() external payable {}

    function run(address account, uint256 amount, bool openMake) public payable {
        require(amount > 0, "amount must be > 0");
        // record balance of this test contract before making state-changing calls
        uint256 beforeBalance = address(this).balance;

        // Prepare to call either openTakeFor or openMakeFor. These functions may revert; capture that.
        bool reverted;
        if (openMake) {
            try c.openMakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openTakeFor(account, UFixed18.wrap(amount)) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // After the call, our contract should not have gained ETH from c (no unexpected transfers outward from c to msg.sender)
        // This asserts that address(this).balance <= beforeBalance.
        // Also assert that even if call reverted due to other reasons, it never made us richer.
        assert(address(this).balance <= beforeBalance);
    }
}

