contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an account and an amount and a selector: 0 => openTakeFor, 1 => openMakeFor
    // The rule: if c.closed() is true before the call, then the attempted open (take or make)
    // must revert. We observe closed() (a public view) and then perform the call and
    // record whether it reverted.
    function run(address account, UFixed18 amount, uint8 kind) public payable {
        require(kind <= 1, "invalid kind");

        // Observe closed flag before making any state-changing call
        bool wasClosed = c.closed();

        bool reverted;
        if (kind == 0) {
            try c.openTakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.openMakeFor(account, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // General rule: if product was closed, the open call must have reverted.
        assert(!wasClosed || reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
