    function run(address account, UFixed18 amount, uint8 kind) public payable {
        require(kind <= 1, "invalid kind");

        // Observe closed flag before making any state-changing call
        bool wasClosed = c.closed();

        bool revertedTake;
        bool revertedMake;

        // Each state-changing call must be a top-level statement. Use try/catch directly.
        try c.openTakeFor(account, amount) {
            revertedTake = false;
        } catch {
            revertedTake = true;
        }

        try c.openMakeFor(account, amount) {
